        for k,v in value.items():
            if k in props:validate(v,props[k],path+'.'+k)
    elif typ=='array':
        assert isinstance(value,list) and len(value)>=schema.get('minItems',0),(path,'array')
        for i,v in enumerate(value):validate(v,schema.get('items',{}),path+f'[{i}]')
    elif typ=='string':assert isinstance(value,str) and len(value)>=schema.get('minLength',0),(path,'string')
    elif typ=='boolean':assert isinstance(value,bool),(path,'bool')
